$("annotationCancelBtn").onclick=()=>{resetAnnotationForm();renderProductionAnnotations()};
function productionBlockForCoordinates(coords){const candidates=state.productionBlocks.filter(block=>coords.x>=block.bounds.x_min&&coords.x<=block.bounds.x_max&&coords.y>=block.bounds.y_min&&coords.y<=block.bounds.y_max);if(!candidates.length)return null;const withZ=candidates.filter(block=>block.bounds.z_min==null||block.bounds.z_max==null||(coords.z>=block.bounds.z_min&&coords.z<=block.bounds.z_max));const pool=withZ.length?withZ:candidates;return pool.sort((a,b)=>(a.bounds.x_max-a.bounds.x_min)*(a.bounds.y_max-a.bounds.y_min)-(b.bounds.x_max-b.bounds.x_min)*(b.bounds.y_max-b.bounds.y_min))[0]}
