function installProductionNavigation(v){const dom=v.renderer.domElement,orbit=v.orbitControls;orbit.addEventListener("drag",e=>{if(e.drag.object!==null)return;const middle=e.drag.mouse===4,lockedLeft=e.drag.mouse===1&&state.productionProfile;if(!middle&&!lockedLeft)return;const scale=v.scene.cameraMode===Potree.CameraMode.ORTHOGRAPHIC?2/3:1;orbit.panDelta.x+=scale*e.drag.lastDrag.x/dom.clientWidth;orbit.panDelta.y+=scale*e.drag.lastDrag.y/dom.clientHeight});window.addEventListener("mouseup",e=>{if(v.inputHandler.drag&&e.target!==dom)v.inputHandler.onMouseUp(e)});dom.addEventListener("mousemove",e=>{const r=dom.getBoundingClientRect();state.productionProfileCursor={x:e.clientX-r.left,y:e.clientY-r.top}});dom.addEventListener("mouseleave",()=>{state.productionProfileCursor=null});document.addEventListener("keydown",e=>{if(e.key!=="Escape"||state.workspace!=="PRODUCTION")return;cancelProductionBox(true);cancelProductionProfileLine()});if(!Potree.Utils.__plaClipAwarePick){const pick=Potree.Utils.getMousePointCloudIntersection;Potree.Utils.getMousePointCloudIntersection=function(mouse,camera,viewer,pointclouds,params={}){return pick.call(this,mouse,camera,viewer,pointclouds,viewer===state.productionViewer?{pickClipped:true,...params}:params)};Potree.Utils.__plaClipAwarePick=true}}
