function markProductionView(){document.querySelectorAll("[data-production-view]").forEach(b=>b.classList.toggle("active",b.dataset.productionView===state.productionViewMode));const v=state.productionViewer,pan=v&&v.controls===v.earthControls;$("productionNavHint").textContent=state.productionProfile?"Drag: pan · Wheel: zoom · Rotation locked in profile":pan?"Left-drag: pan · Right-drag: rotate · Wheel: zoom to cursor":"Left-drag: rotate · Right/middle-drag: pan · Wheel: zoom · Double-click: centre"}
