function setProductionView(mode,{yaw,pitch,pivot=null,radius=null}){const v=state.productionViewer,view=v.scene.view,target=pivot||view.getPivot();v.setCameraMode(mode==="3d"?Potree.CameraMode.PERSPECTIVE:Potree.CameraMode.ORTHOGRAPHIC);view.yaw=yaw;view.pitch=pitch;if(radius)view.radius=radius;view.position.copy(target).sub(view.direction.multiplyScalar(view.radius));v.orbitControls.stop();state.productionViewMode=mode;markProductionView()}
function saveProductionCamera(){const v=state.productionViewer,view=v.scene.view;return {mode:v.scene.cameraMode,yaw:view.yaw,pitch:view.pitch,radius:view.radius,position:view.position.clone(),viewMode:state.productionViewMode}}
