const productionViews={top:{yaw:0,pitch:-Math.PI/2},front:{yaw:0,pitch:0},side:{yaw:Math.PI/2,pitch:0},"3d":{yaw:Math.PI/4,pitch:-Math.PI/4}};
document.querySelectorAll("[data-production-view]").forEach(btn=>btn.onclick=()=>{const v=state.productionViewer;if(!v||!state.productionPointclouds.length)return;cancelProductionBox(false);cancelProductionProfileLine();exitProductionProfile(false);const mode=btn.dataset.productionView;setProductionView(mode,{...productionViews[mode],yaw:mode==="3d"?v.scene.view.yaw:productionViews[mode].yaw})});
$("productionNavModeBtn").onclick=()=>{const v=state.productionViewer;if(!v||state.productionProfile)return;const pan=v.controls!==v.earthControls;v.setControls(pan?v.earthControls:v.orbitControls);$("productionNavModeBtn").textContent=pan?"Pan":"Orbit";markProductionView()};
