$("productionBoxBtn").onclick=()=>{if(state.productionBoxTool)cancelProductionBox(true);else startProductionBox()};
$("productionCloseBoxBtn").onclick=()=>{clearProductionClip(true);toast("Bounding box removed. Full point cloud restored.","success")};
$("productionFitBtn").onclick=()=>{if(!state.productionViewer)return;if(state.productionProfile){applyProductionProfile(true);return}if(state.productionClipVolume){state.productionClipVolume.updateMatrixWorld(true);state.productionViewer.zoomTo(state.productionClipVolume,.7,350)}else state.productionViewer.fitToScreen(.8)};
// Vertical section (MicroStation/TerraScan style): a section line plus depth clips a slab that is viewed orthographically from its side.
