function productionPointAt(px,py){const v=state.productionViewer,I=Potree.Utils.getMousePointCloudIntersection({x:px,y:py},v.scene.getActiveCamera(),v,v.scene.pointclouds);if(I)return I.location.clone();if(v.scene.cameraMode===Potree.CameraMode.ORTHOGRAPHIC&&Math.abs(v.scene.view.pitch+Math.PI/2)<.01){const p=productionOrthoWorld(px,py),bounds=v.getBoundingBox(v.scene.pointclouds);p.z=(bounds.min.z+bounds.max.z)/2;return p}return null}
function cancelProductionProfileLine(){const line=state.productionProfileLine;if(!line)return;state.productionProfileLine=null;line.cancel();$("productionProfileBtn").textContent="Profile";if(!state.productionProfile)$("productionProfileBtn").classList.remove("active")}
function startProductionProfileLine(){const v=state.productionViewer;if(!v||!state.productionPointclouds.length)return;cancelProductionBox(true);cancelProductionProfileLine();v.dispatchEvent({type:"cancel_insertions"});const dom=v.renderer.domElement,points=[];let down=null,marker=null;const onDown=e=>{down={x:e.clientX,y:e.clientY}};const onUp=e=>{if(e.button!==0||!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>4)return;const r=dom.getBoundingClientRect(),point=productionPointAt(e.clientX-r.left,e.clientY-r.top);if(!point){toast("No LiDAR point under the cursor. Click on the point cloud or switch to Top view.","error",4200);return}points.push(point);if(points.length===1){addProductionMeasurement([point],{name:"Section start",color:0x53d9ff,coordinates:true});marker=state.productionMeasurements[state.productionMeasurements.length-1];toast("Now click the end of the section line.","info",3600);return}cancelProductionProfileLine();enterProductionProfile(points[0],points[1])};dom.addEventListener("mousedown",onDown);dom.addEventListener("mouseup",onUp);state.productionProfileLine={cancel:()=>{dom.removeEventListener("mousedown",onDown);dom.removeEventListener("mouseup",onUp);if(marker){v.scene.removeMeasurement(marker);state.productionMeasurements=state.productionMeasurements.filter(m=>m!==marker)}}};$("productionProfileBtn").classList.add("active");$("productionProfileBtn").textContent="Cancel profile (Esc)";toast("Click the start of the section line. Top view gives the most precise line.","info",4600)}
function enterProductionProfile(a,b){const len=Math.hypot(b.x-a.x,b.y-a.y);if(len<1){toast("Pick two points further apart to define the section line.","error");return}const v=state.productionViewer;clearProductionClip(false);const previous=state.productionProfile?.previous||saveProductionCamera();exitProductionProfile(false);const p={a:{x:a.x,y:a.y,z:a.z},b:{x:b.x,y:b.y,z:b.z},len,depth:Math.max(.5,Number($("productionProfileDepth").value)||10),offset:0,previous,volume:null};state.productionProfile=p;v.setControls(v.orbitControls);$("productionNavModeBtn").textContent="Orbit";v.orbitControls.rotationSpeed=0;$("productionProfileBar").classList.remove("hidden");$("productionProfileOverlay").classList.remove("hidden");$("productionProfileBtn").classList.add("active");document.querySelectorAll("[data-profile-pick]").forEach(btn=>btn.disabled=!can("production.annotate"));applyProductionProfile(true);const loop=()=>{if(state.productionProfile!==p)return;drawProductionProfileOverlay();requestAnimationFrame(loop)};requestAnimationFrame(loop)}
function productionProfileFrame(p=state.productionProfile){const u={x:(p.b.x-p.a.x)/p.len,y:(p.b.y-p.a.y)/p.len},n={x:-u.y,y:u.x};return {u,n,cx:(p.a.x+p.b.x)/2+n.x*p.offset,cy:(p.a.y+p.b.y)/2+n.y*p.offset,cz:(p.a.z+p.b.z)/2,yaw:Math.atan2(u.y,u.x)}}
function applyProductionProfile(refit=false){const v=state.productionViewer,p=state.productionProfile;if(!v||!p)return;const f=productionProfileFrame(p),bounds=v.getBoundingBox(v.scene.pointclouds),unit=productionUnitLabel();if(!p.volume){p.volume=new Potree.BoxVolume();p.volume.name="Production profile";p.volume.visible=false;p.volume.clip=true;v.scene.addVolume(p.volume)}p.volume.position.set(f.cx,f.cy,(bounds.min.z+bounds.max.z)/2);p.volume.rotation.set(0,0,f.yaw);p.volume.scale.set(p.len,p.depth,bounds.max.z-bounds.min.z+20);p.volume.updateMatrixWorld(true);v.setClipMethod(Potree.ClipMethod.INSIDE_ANY);v.setClipTask(Potree.ClipTask.SHOW_INSIDE);if(refit)setProductionView("profile",{yaw:f.yaw,pitch:0,pivot:new THREE.Vector3(f.cx,f.cy,f.cz),radius:p.len/2*1.08});$("productionProfileInfo").textContent=`Section ${p.len.toFixed(1)} ${unit} · depth ${p.depth} ${unit} · offset ${p.offset>=0?"+":""}${p.offset.toFixed(1)} ${unit}`;markProductionView()}
function stepProductionProfile(sign){const p=state.productionProfile,v=state.productionViewer;if(!p)return;const f=productionProfileFrame(p);p.offset+=sign*p.depth;v.scene.view.position.x+=f.n.x*sign*p.depth;v.scene.view.position.y+=f.n.y*sign*p.depth;applyProductionProfile(false)}
function rotateProductionProfile(){const p=state.productionProfile;if(!p)return;const f=productionProfileFrame(p),half=p.len/2,sign=p.rotated?-1:1,dir={x:f.n.x*sign,y:f.n.y*sign};p.a={x:f.cx-dir.x*half,y:f.cy-dir.y*half,z:f.cz};p.b={x:f.cx+dir.x*half,y:f.cy+dir.y*half,z:f.cz};p.offset=0;p.rotated=!p.rotated;applyProductionProfile(true)}
