  for(let z=Math.ceil(zBottom/zStep)*zStep;z<=zTop;z+=zStep){const y=Math.round(toY(z))+.5;ctx.strokeStyle="rgba(150,190,210,.16)";ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(plotW,y);ctx.stroke();ctx.strokeStyle="#6f97a8";ctx.beginPath();ctx.moveTo(plotW,y);ctx.lineTo(plotW+7,y);ctx.stroke();ctx.fillStyle="#cfe3ea";ctx.fillText(z.toFixed(zDec),plotW+10,y)}
  ctx.fillStyle="#8fb2c0";ctx.fillText(`Elev (${unit})`,plotW+8,12);
