  for(let s=Math.ceil(s0/sStep)*sStep;s<=s1;s+=sStep){const x=Math.round(w/2+(s-sc)*scale)+.5;ctx.strokeStyle="#6f97a8";ctx.beginPath();ctx.moveTo(x,plotH);ctx.lineTo(x,plotH+5);ctx.stroke();ctx.fillStyle="#cfe3ea";ctx.fillText(s.toFixed(sStep<1?1:0),x,plotH+14)}
  ctx.strokeStyle="rgba(83,217,255,.45)";ctx.setLineDash([3,5]);for(const s of [0,p.len]){const x=Math.round(w/2+(s-sc)*scale)+.5;if(x>0&&x<plotW){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,plotH);ctx.stroke()}}ctx.setLineDash([]);
  // Saved points inside the slab, labelled with elevation and height above the pole base
