  const baseNear=x=>bases.find(r=>pole&&String(r.pole_internal_id??r.attributes?.pole_internal_id)===pole)||bases.slice().sort((a,b)=>Math.abs(toX(a.coordinates)-x)-Math.abs(toX(b.coordinates)-x))[0];
  const items=rows.filter(r=>r.id!==$("annotationId").value).map(r=>({pt:r.coordinates,label:r.feature_type,color:productionFamilyCss[r.family]||"#ffffff",base:r.feature_type==="Pole Base / Ground Point"}));
