const productionPickPresets={base:{label:"Pole base",family:"Pole Points",feature:"Pole Base / Ground Point"},top:{label:"Pole top",family:"Pole Points",feature:"Pole Top Point"},attachment:{label:"Attachment",family:"Electrical / Communication Attachment Points",feature:"Communication Attachment Points"}};
document.querySelectorAll("[data-profile-pick]").forEach(btn=>btn.onclick=()=>startProductionPick(productionPickPresets[btn.dataset.profilePick]));
$("productionProfileBtn").onclick=()=>{if(state.productionProfileLine)cancelProductionProfileLine();else if(state.productionProfile)exitProductionProfile(true);else startProductionProfileLine()};
$("productionProfilePrevBtn").onclick=()=>stepProductionProfile(-1);
$("productionProfileNextBtn").onclick=()=>stepProductionProfile(1);
$("productionProfileRotateBtn").onclick=rotateProductionProfile;
$("productionProfileDepth").onchange=()=>{const p=state.productionProfile;if(!p)return;p.depth=Math.max(.5,Number($("productionProfileDepth").value)||10);$("productionProfileDepth").value=p.depth;applyProductionProfile(false)};
$("productionProfileExitBtn").onclick=()=>exitProductionProfile(true);
$("productionUploadBtn").onclick=()=>{$("productionUploadForm").reset();$("productionCustomer").value="PLA";$("productionCrs").value="EPSG:6424";$("productionUnits").value="US survey foot";$("productionUploadProgress").classList.add("hidden");$("productionUploadError").textContent="";$("productionUploadDialog").showModal()};
$("cancelProductionUpload").onclick=()=>$("productionUploadDialog").close();
$("productionUploadForm").onsubmit=async ev=>{ev.preventDefault();$("productionUploadError").textContent="";try{const workbook=$("productionWorkbookFile").files[0],lidar=[...$("productionLidarFiles").files];if(!workbook)throw new Error("Select the client pole workbook");if(!lidar.length)throw new Error("Select at least one LAS, LAZ, or COPC file");const files=[workbook,...lidar];productionProgress(2,"Creating production dataset…");const project=await api("/api/projects",{method:"POST",body:JSON.stringify({name:$("productionDatasetName").value.trim(),customer:$("productionCustomer").value.trim()||"PLA",crs:$("productionCrs").value.trim(),units:$("productionUnits").value.trim()})});for(let i=0;i<files.length;i++)await sendFile(project.id,files[i],i===0?"WORKBOOK":"LIDAR_SOURCE",i,files.length,productionProgress);productionProgress(60,"Queueing LiDAR conversion and pole import…");const queued=await api(`/api/projects/${project.id}/process-lidar`,{method:"POST"});state.projectId=project.id;localStorage.setItem("pla_project_id",project.id);for(;;){await new Promise(r=>setTimeout(r,1800));const job=await api(`/api/jobs/${queued.job_id}`);productionProgress(60+Math.round(job.progress*.4),`${job.stage} · ${job.progress}%`);if(job.status==="SUCCEEDED")break;if(job.status==="FAILED")throw new Error(job.error||"Production processing failed")}productionProgress(100,"LiDAR and pole catalogue ready");await new Promise(r=>setTimeout(r,400));$("productionUploadDialog").close();await bootstrap();toast(`${lidar.length} LiDAR file${lidar.length===1?"":"s"} and workbook ready.`,"success")}catch(e){$("productionUploadError").textContent=e.message;productionProgress(0,"Import stopped")}};

